  offsets[1] = vec2( -2.0, 0.0 );
  offsets[2] = vec2( 0.0, 2.0 );
  offsets[3] = vec2( 0.0, -2.0 );
  offsets[4] = vec2( 2.0, 2.0 );
  offsets[5] = vec2( -2.0, 2.0 );
  offsets[6] = vec2( 2.0, -2.0 );
  offsets[7] = vec2( -2.0, -2.0 );
  offsets[8] = vec2( 8.0, 0.0 );
  offsets[9] = vec2( -8.0, 0.0 );
